/**
 * Unified PMXT types shared by every widget.
 *
 * Market-data shapes mirror the pmxt catalog API (`api.pmxt.dev`); trading
 * shapes mirror the documented PMXT hosted trading API (`trade.pmxt.dev`)
 * `/v0` wire format — the same surface the official pmxt SDKs use.
 */

/** Venues the catalog API can read from. */
export type CatalogVenue =
    | 'polymarket'
    | 'kalshi'
    | 'limitless'
    | 'opinion'
    | (string & {});

/** Venues that settle through PMXT escrow (tradable venues). */
export type TradingVenue = 'polymarket' | 'opinion' | 'limitless';

/** A single tradable outcome of a market. */
export interface PmxtOutcome {
    /** Venue-native outcome id (e.g. Polymarket token id). */
    outcomeId: string;
    /** Venue-native id of the parent market. */
    marketId: string;
    /** Display label, e.g. "Yes" or a group item like "Paraguay". */
    label: string;
    /** Last price as a decimal probability, 0–1. */
    price: number;
    /** Absolute 24h price change (0.03 = +3pts); null when unknown. */
    priceChange24h: number | null;
    /** Best bid price; null when the book side is empty or not reported. */
    bestBid: number | null;
    /** Best ask price; null when the book side is empty or not reported. */
    bestAsk: number | null;
    /** Venue-specific extras (e.g. `opinionMarketId` on Opinion outcomes). */
    metadata: Record<string, unknown>;
}

/** A single market (question) from the catalog API. */
export interface PmxtMarket {
    /** Catalog UUID. */
    id: string;
    /** Venue-native market id. */
    marketId: string;
    /** Catalog UUID of the parent event. */
    eventId: string;
    /** Full title, joined by the catalog as `"{event title} - {question}"`. */
    title: string;
    slug: string;
    /** null when the venue provides none. */
    description: string | null;
    /** Link to the market on the source venue. */
    url: string;
    /** Image URL; null when the venue provides none. */
    image: string | null;
    category: string | null;
    tags: string[] | null;
    /** Lifetime traded volume in USD. */
    volume: number;
    /** Trailing-24h traded volume in USD. */
    volume24h: number;
    /** Available liquidity in USD. */
    liquidity: number;
    /** Minimum price increment; null when the venue doesn't report one. */
    tickSize: number | null;
    /** ISO trading-close/resolution time; null when the venue reports none. */
    resolutionDate: string | null;
    /** Venue-reported status (e.g. "active"); null when unknown. */
    status: string | null;
    /** On-chain contract address; null when not applicable. */
    contractAddress: string | null;
    outcomes: PmxtOutcome[];
    /** YES slot for binary markets; absent for multi-outcome markets. */
    yes?: PmxtOutcome;
    /** NO slot for binary markets; absent for multi-outcome markets. */
    no?: PmxtOutcome;
    /** Venue the market came from, when the endpoint reports it. */
    sourceExchange?: CatalogVenue | null;
}

/** An event grouping one or more related markets. */
export interface PmxtEvent {
    /** Catalog UUID. */
    id: string;
    /** Venue the event came from; null when not reported. */
    sourceExchange: CatalogVenue | null;
    title: string;
    /** null when the venue provides none. */
    description: string | null;
    slug: string;
    /** Nested markets, each with outcomes and prices. */
    markets: PmxtMarket[];
    /** Lifetime traded volume in USD across all nested markets. */
    volume: number;
    /** Trailing-24h traded volume in USD across all nested markets. */
    volume24h: number;
    /** Link to the event on the source venue. */
    url: string;
    /** Image URL; null when the venue provides none. */
    image: string | null;
    category: string | null;
    tags: string[] | null;
}

/** One price level of an order book side. */
export interface OrderBookLevel {
    /** Price per share, 0–1. */
    price: number;
    /** Shares available at this price. */
    size: number;
}

/** Order book snapshot; best price first on each side. */
export interface OrderBook {
    bids: OrderBookLevel[];
    asks: OrderBookLevel[];
    /** Snapshot time in epoch ms, when the venue reports it. */
    timestamp?: number;
}

/** OHLCV candle from the catalog `fetchOHLCV` endpoint. */
export interface PriceCandle {
    /** Candle open time in epoch ms. */
    timestamp: number;
    open: number;
    high: number;
    low: number;
    close: number;
    /** Traded volume during the candle, when reported. */
    volume?: number;
}

/** Public trade from the catalog `fetchTrades` endpoint. */
export interface PublicTrade {
    /** Fill price per share, 0–1. */
    price: number;
    /** Shares traded. */
    amount: number;
    /** Taker side; null/absent when the venue doesn't report it. */
    side?: 'buy' | 'sell' | null;
    /** Fill time in epoch ms; null/absent when unknown. */
    timestamp?: number | null;
}

/** One cross-venue market match from the router (`fetchMarketMatches`). */
export interface MarketMatch {
    sourceMarket: PmxtMarket;
    market: PmxtMarket;
    relation?: string;
    /** Match confidence, 0–1. */
    confidence?: number;
}

/** The same real-world event matched across venues. */
export interface EventCluster {
    clusterId?: string;
    /** Normalized title shared by all legs. */
    canonicalTitle: string;
    category?: string | null;
    /** Match confidence, 0–1. */
    confidence?: number;
    /** Combined 24h volume across legs (USD). */
    volume24h?: number;
    /** One event per venue, each with `sourceExchange` set. */
    events: PmxtEvent[];
}

/** The same real-world market matched across venues (one leg per venue). */
export interface MarketCluster {
    /** Normalized title shared by all legs. */
    canonicalTitle: string;
    /** One leg per venue, each with `sourceExchange` guaranteed set. */
    markets: Array<PmxtMarket & { sourceExchange: CatalogVenue }>;
    /** Match confidence, 0–1. */
    confidence?: number;
    matchedCount?: number;
}

/** Result of walking an order book to fill a given size (VWAP quote). */
export interface ExecutionPrice {
    /** Volume-weighted average fill price. */
    averagePrice: number;
    /** Shares fillable at the available depth. */
    filledAmount: number;
    /** Total cost (buy) or proceeds (sell) in USD. */
    totalCost: number;
    /** True when the book is too shallow to fill the full size. */
    partialFill: boolean;
}

// ---- Hosted trading wire format (trade.pmxt.dev /v0) --------------------

/** EIP-712 typed-data payload to sign with the user's wallet. */
export interface TypedData {
    types: Record<string, Array<{ name: string; type: string }>>;
    domain: {
        name: string;
        version: string;
        chainId: number;
        verifyingContract: `0x${string}`;
    };
    primaryType: string;
    message: Record<string, string | number | boolean>;
}

/**
 * `POST /v0/trade/build-order` request. Identify the outcome with EITHER a
 * catalog `outcome_id` UUID OR a `(venue, venue_outcome_id)` pair — exactly
 * one of the two shapes.
 *
 * Denomination rules: market buy → `denom: 'usdc'` (amount is a USDC
 * budget); market sell and all limit orders → `denom: 'shares'`.
 */
export interface BuildOrderRequest {
    /** Catalog market UUID, when known. */
    market_id?: string;
    /** Catalog outcome UUID — first identification shape. */
    outcome_id?: string;
    /** Venue for the `(venue, venue_outcome_id)` identification shape. */
    venue?: TradingVenue;
    /** Venue-native outcome id (e.g. Polymarket token id). */
    venue_outcome_id?: string;
    side: 'buy' | 'sell';
    order_type: 'market' | 'limit';
    /** USDC budget or share count, per `denom`. */
    amount: number;
    /** What `amount` denominates — see denomination rules above. */
    denom: 'usdc' | 'shares';
    /** Required for limit orders. Decimal price per share (0–1]. */
    price?: number;
    /** Max acceptable slippage, in percent. */
    slippage_pct?: number;
    /** Wallet address that will sign and own the order. */
    user_address: string;
}

/** Server-side execution quote attached to a built order. */
export interface BuildOrderQuote {
    /** Best price at the top of the book. */
    best_price: number;
    /** Expected volume-weighted average fill price. */
    expected_avg_price: number;
    /** Expected slippage from best price, in percent. */
    expected_slippage_pct: number;
    /** Estimated USDC cost (buy) or proceeds (sell). */
    estimated_cost_or_proceeds: number;
    /** False when the book is too shallow to fill the order. */
    fillable: boolean;
    /** Liquidity available on the relevant book side. */
    liquidity: number;
    /** Fee charged on the order, in USDC. */
    fee_amount: number;
    /** Venue tick size, as a decimal string. */
    tick_size: string;
}

/** Venue-native fields the server resolved from catalog UUIDs. */
export interface ResolvedOutcome {
    venue: TradingVenue;
    /** Venue-native outcome/token id. */
    token_id: string;
    /** Polymarket neg-risk market flag. */
    neg_risk: boolean;
    /** Minimum price increment. */
    tick_size: number;
    /** Opinion's numeric market id; null/absent for other venues. */
    opinion_market_id?: number | null;
}

/** `POST /v0/trade/build-order` response. */
export interface BuiltOrder {
    /** Pass back in `SubmitOrderRequest` after signing. */
    built_order_id: string;
    side: 'buy' | 'sell';
    /** EIP-712 payload the user must sign. */
    typed_data: TypedData;
    /** Second EIP-712 payload for cross-chain (Opinion) sells — BSC pull leg. */
    pull_typed_data?: TypedData | null;
    quote: BuildOrderQuote;
    resolved?: ResolvedOutcome | null;
}

/** `POST /v0/trade/submit-order` request. */
export interface SubmitOrderRequest {
    built_order_id: string;
    /** Signature over the built order's `typed_data`. */
    signature: `0x${string}`;
    /** Signature over `pull_typed_data`; required when the build returned one. */
    pull_signature?: `0x${string}`;
    /** Block until the order reaches a terminal status. */
    wait?: boolean;
}

/** Echoed when reverse-resolution misses, so callers can still act. */
export interface RawTokenRef {
    venue: TradingVenue;
    token_id: string;
}

/**
 * Unified `/v0` order shape (submit/cancel responses, open-orders reads).
 * Submit statuses: accepted | pending | fulfilled | failed | unknown |
 * resting. Open-order statuses: resting | partial. Cancel statuses:
 * cancellation_requested | cancelled | failed.
 */
export interface PmxtOrder {
    id: string;
    market_id?: string | null;
    outcome_id?: string | null;
    side?: 'buy' | 'sell' | null;
    type?: 'market' | 'limit' | null;
    /** Order size in decimal shares (not micro-shares), when reported. */
    amount?: number | null;
    /** Limit price per share, when applicable. */
    price?: number | null;
    /** Shares filled so far. */
    filled: number;
    /** Shares still resting. */
    remaining: number;
    status: string;
    fee?: number | null;
    /** ISO-8601 creation time. */
    timestamp?: string | null;
    /** Settlement transaction hash, once on-chain. */
    tx_hash?: string | null;
    /** Settlement chain, e.g. "polygon" or "bsc". */
    chain?: string | null;
    block_number?: number | null;
    raw?: RawTokenRef | null;
    /** Present on open-order reads from some deployments. */
    market_title?: string | null;
    /**
     * Operator-reported failure reason on `status: 'failed'` / `'no_fill'`
     * orders, surfaced from the latest `task_state_log` row. Drives the
     * error copy in the order-ticket Done stage.
     */
    error?: string | null;
}

/** Unified `/v0` user trade shape. `amount` is in 6-dec micro-shares. */
export interface PmxtUserTrade {
    id?: string | null;
    market_id?: string | null;
    outcome_id?: string | null;
    side?: 'buy' | 'sell' | null;
    amount?: number | null;
    /** Fill price per share, 0–1. */
    price?: number | null;
    fee?: number | null;
    /** ISO-8601 fill time. */
    timestamp?: string | null;
    tx_hash?: string | null;
    /** Settlement chain, e.g. "polygon" or "bsc". */
    chain?: string | null;
    venue?: TradingVenue | null;
    raw?: RawTokenRef | null;
}

/** Unified `/v0` position shape. `shares` is a decimal share count. */
export interface PmxtPosition {
    market_id?: string | null;
    outcome_id?: string | null;
    venue: TradingVenue;
    shares: number;
    /** Latest mark price per share; null when unknown. */
    current_price?: number | null;
    /** Shares × current price, in USD; null when unknown. */
    current_value?: number | null;
    /** Display label, e.g. "Yes". */
    outcome_label?: string | null;
    /** Average entry price; null when not reported. */
    entry_price?: number | null;
    /** Realized profit in USD; null when not reported. */
    realized_pnl?: number | null;
    raw?: RawTokenRef | null;
}

/** Escrow balance row from the `/v0` trading API. */
export interface PmxtBalance {
    /** Currency code, e.g. "usdc". */
    currency: string;
    /** Balance in whole currency units. */
    amount: number;
    /** Venue the balance is held for; null for the aggregate. */
    venue?: TradingVenue | null;
}

/** Request to build a cancel payload for signing (start of sign-and-cancel). */
export interface CancelBuildRequest {
    /** Id of the resting order to cancel. */
    order_id: string;
    /** Wallet address that owns the order. */
    user_address: string;
}

/** Cancel payload(s) to sign, plus the id to submit them under. */
export interface CancelBuildResponse {
    cancel_id: string;
    /** EIP-712 payload the user must sign. */
    typed_data: TypedData;
    /** Second EIP-712 payload for cross-chain (Opinion) cancels — BSC pull leg. */
    pull_typed_data?: TypedData | null;
    /** Unix timestamp after which the signatures expire. */
    deadline: number;
}

/** Final cancel submission carrying the user's signature(s). */
export interface CancelRequest {
    cancel_id: string;
    signature: `0x${string}`;
    /** Required when the build returned `pull_typed_data`. */
    pull_signature?: `0x${string}`;
}

/**
 * A market+outcome the user picked to trade. Produced by discovery widgets
 * (MarketSearch, TopMarkets, MarketCard) and consumed by OrderTicket.
 *
 * `tokenId` is the venue-native outcome id straight from the catalog
 * (`outcome.outcomeId`). When catalog UUIDs are known (e.g. rows from
 * Positions), `marketUuid`/`outcomeUuid` are set and OrderTicket
 * prefers them for build-order identification.
 */
export interface PickedMarket {
    /** Parent event title, for display. */
    eventTitle: string;
    /** Market question, stripped of the event-title prefix. */
    question: string;
    /** Outcome display label, e.g. "Yes". */
    outcome: string;
    tokenId: string;
    /** Polymarket neg-risk market flag. */
    negRisk: boolean;
    /** Last known price, used as the ticket's initial estimate. */
    price: number;
    venue: TradingVenue;
    /** Opinion's numeric market id (opinion venue only). */
    opinionMarketId?: number;
    /**
     * Shares already held, when the pick comes from a position row. Trumps
     * OrderTicket's own /v0 lookup — escrow-sourced positions don't appear
     * there.
     */
    heldShares?: number;
    /** Catalog market UUID, when known. */
    marketUuid?: string;
    /** Catalog outcome UUID, when known. */
    outcomeUuid?: string;
}

// ---- Escrow funding (deposit / withdraw) --------------------------------

/** An unsigned EVM transaction returned by the escrow build endpoints. */
export interface UnsignedTx {
    to: `0x${string}`;
    /** Wei value as a decimal string ("0" for escrow calls). */
    value: string;
    data: `0x${string}`;
    chainId: number;
}

/** Response of `/escrow/build-approve|build-deposit|build-withdrawal`. */
export interface BuildTxResponse {
    tx: UnsignedTx;
}

/** The single in-flight timelocked withdrawal for an address. */
export interface PendingWithdrawal {
    amount_wei: number;
    amount_usdc: number;
    /** Unix timestamp when the withdrawal becomes claimable. */
    claimable_at: number;
    is_claimable: boolean;
}

/** One historical withdrawal lifecycle event. */
export interface WithdrawalEvent {
    type: 'requested' | 'claimed' | 'cancelled';
    amount_wei: number;
    amount_usdc: number;
    tx_hash: `0x${string}`;
    block_number: number;
    claimable_at: number | null;
}

/** Response of `/escrow/withdrawals/{address}`. */
export interface WithdrawalsResponse {
    address: string;
    pending?: PendingWithdrawal;
    events?: WithdrawalEvent[];
}

/** Response of `/user/escrow-balances`. */
export interface EscrowBalancesResponse {
    address: string;
    usdc: {
        escrow_balance_wei: number;
        escrow_balance_tokens: number;
    };
    tokens: Array<{
        wrapped_address: string;
        token_id: string | null;
        venue: string | null;
        wrapped_symbol: string | null;
        market_title: string | null;
        outcome_name: string | null;
        market_id: number | null;
        escrow_balance_wei: number;
        escrow_balance_tokens: number;
    }>;
    size: number;
    from: number;
}

/** Sub-$1 prices render in cents ("62.5¢"), everything else as dollars. */
export function formatPrice(price: number | null | undefined): string {
    if (price == null || !Number.isFinite(price)) return '—';
    if (price < 0 || price >= 1) return `$${price.toFixed(3)}`;
    return `${(price * 100).toFixed(1)}¢`;
}

/** Compact volume: $1.2M, $340K, $87. */
export function formatVolume(volume: number | null | undefined): string {
    if (volume == null || !Number.isFinite(volume)) return '—';
    if (volume >= 1_000_000_000) return `$${(volume / 1_000_000_000).toFixed(1)}B`;
    if (volume >= 1_000_000) return `$${(volume / 1_000_000).toFixed(1)}M`;
    if (volume >= 1_000) return `$${(volume / 1_000).toFixed(0)}K`;
    return `$${volume.toFixed(0)}`;
}

/** Dollar amount with thousands separators and exactly two decimals. */
export function formatUsd(amount: number | null | undefined): string {
    if (amount == null || !Number.isFinite(amount)) return '—';
    return `$${amount.toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    })}`;
}

/**
 * Probability as a whole percentage: 0.625 → "63%". Longshots never show a
 * misleading flat 0%/100% — they render as "<1%" / ">99%".
 */
export function formatPercent(price: number | null | undefined): string {
    if (price == null || !Number.isFinite(price)) return '—';
    if (price > 0 && price < 0.01) return '<1%';
    if (price > 0.99 && price < 1) return '>99%';
    return `${Math.round(price * 100)}%`;
}

/** Share count truncated (not rounded) to 4 decimals. */
export function formatShares(shares: number | null | undefined): string {
    if (shares == null || !Number.isFinite(shares)) return '—';
    return truncate4(shares).toString();
}

/** Round to 2 decimal places. */
export function round2(n: number): number {
    return Math.round(n * 100) / 100;
}

/** Truncate to 4 decimal places (floors — never rounds up). */
export function truncate4(n: number): number {
    return Math.floor(n * 10000) / 10000;
}

/** "0x1234…abcd"-style truncation; returns short inputs unchanged. */
export function shortAddress(address: string | null | undefined): string {
    if (!address || address.length < 10) return address ?? '—';
    return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

/** Relative time ("5m ago") from an ISO string or epoch-ms timestamp. */
export function formatTimeAgo(input: string | number | null | undefined): string {
    if (input == null) return '—';
    const ts = typeof input === 'string' ? Date.parse(input) : input;
    if (!Number.isFinite(ts)) return '—';
    const diff = Date.now() - ts;
    if (diff < 0) return 'now';
    const mins = Math.floor(diff / 60_000);
    if (mins < 1) return 'just now';
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
}

const MONTHS = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

/** Result of {@link formatExpiry}: display label plus expired flag. */
export interface ExpiryInfo {
    /** e.g. "Ends in 3d", "Ends Jul 20", "Ended Mar 26". */
    label: string;
    /** True when the close time is in the past. */
    expired: boolean;
}

/**
 * Market close/resolution time as a compact label. Near closes render as a
 * countdown ("Ends in 5h"); a week or more out shows the calendar date, with
 * the year appended when it isn't the current year. Returns null for missing
 * or unparseable input so callers can skip rendering entirely.
 */
export function formatExpiry(
    input: string | number | null | undefined,
): ExpiryInfo | null {
    if (input == null) return null;
    const ts = typeof input === 'string' ? Date.parse(input) : input;
    if (!Number.isFinite(ts)) return null;

    const now = Date.now();
    const date = new Date(ts);
    const day = `${MONTHS[date.getUTCMonth()]} ${date.getUTCDate()}`;
    const year = date.getUTCFullYear();
    const dateLabel =
        year === new Date(now).getUTCFullYear() ? day : `${day}, ${year}`;

    if (ts <= now) return { label: `Ended ${dateLabel}`, expired: true };

    const mins = Math.floor((ts - now) / 60_000);
    if (mins < 60) return { label: `Ends in ${Math.max(mins, 1)}m`, expired: false };
    const hours = Math.floor(mins / 60);
    if (hours < 24) return { label: `Ends in ${hours}h`, expired: false };
    const days = Math.floor(hours / 24);
    if (days < 7) return { label: `Ends in ${days}d`, expired: false };
    return { label: `Ends ${dateLabel}`, expired: false };
}

/**
 * Widgets embed on third-party sites, so only render catalog images served
 * over https — anything else (data:, http:, garbage) is dropped.
 */
export function safeImageUrl(url: string | null | undefined): string | null {
    return url && url.startsWith('https://') ? url : null;
}

const VENUE_LABELS: Record<string, string> = {
    polymarket: 'Polymarket',
    kalshi: 'Kalshi',
    limitless: 'Limitless',
    opinion: 'Opinion',
    probable: 'Probable',
};

/** Human-readable venue name ("polymarket" → "Polymarket"); capitalizes unknown venues. */
export function venueLabel(venue: string | null | undefined): string {
    if (!venue) return 'Unknown';
    return VENUE_LABELS[venue] ?? venue.charAt(0).toUpperCase() + venue.slice(1);
}

import type {
    BuildOrderRequest,
    BuildTxResponse,
    BuiltOrder,
    CancelBuildRequest,
    CancelBuildResponse,
    CancelRequest,
    CatalogVenue,
    EscrowBalancesResponse,
    ExecutionPrice,
    EventCluster,
    MarketCluster,
    MarketMatch,
    OrderBook,
    PmxtBalance,
    PmxtEvent,
    PmxtMarket,
    PmxtOrder,
    PmxtPosition,
    PmxtUserTrade,
    PriceCandle,
    PublicTrade,
    SubmitOrderRequest,
    WithdrawalsResponse,
} from './types';

export interface PmxtClientConfig {
    /**
     * Base URL for the pmxt catalog API. Point this at your own server-side
     * proxy (recommended — keeps your API key off the browser), or directly
     * at https://api.pmxt.dev for server-side usage.
     */
    apiUrl: string;
    /** Base URL for the PMXT trading API (or your proxy in front of it). */
    tradeUrl?: string;
    /**
     * Optional API key sent as a Bearer token. Only set this when calling
     * PMXT directly from a trusted environment — never ship it to browsers.
     */
    apiKey?: string;
}

export class PmxtApiError extends Error {
    readonly status: number;
    readonly body: string;

    constructor(status: number, body: string) {
        super(extractErrorMessage(body) ?? `PMXT request failed (${status})`);
        this.name = 'PmxtApiError';
        this.status = status;
        this.body = body;
    }
}

function extractErrorMessage(body: string): string | null {
    try {
        const json = JSON.parse(body) as Record<string, unknown>;
        const detail =
            (json.detail as { detail?: string })?.detail ??
            json.detail ??
            json.error ??
            json.message;
        if (typeof detail === 'string') return detail;
        if (detail != null) return JSON.stringify(detail);
        return null;
    } catch {
        return body || null;
    }
}

type Envelope<T> = { success?: boolean; data?: T; error?: unknown };

/** Catalog responses arrive bare or wrapped in `{success, data}` — accept both. */
export function unwrapEnvelope<T>(raw: unknown): T {
    if (
        raw != null &&
        typeof raw === 'object' &&
        !Array.isArray(raw) &&
        ('data' in raw || 'success' in raw)
    ) {
        const env = raw as Envelope<T>;
        if (env.success === false) {
            throw new PmxtApiError(400, JSON.stringify(env.error ?? env));
        }
        if (env.data !== undefined) return env.data;
    }
    return raw as T;
}

/**
 * Thin fetch client for the PMXT catalog + trading APIs. Every widget talks
 * through this — swap `apiUrl`/`tradeUrl` to point at your own proxies.
 */
export class PmxtClient {
    readonly config: PmxtClientConfig;

    constructor(config: PmxtClientConfig) {
        this.config = config;
    }

    private async request<T>(
        base: string,
        path: string,
        init: RequestInit = {},
    ): Promise<T> {
        const url = `${base.replace(/\/$/, '')}${path.startsWith('/') ? path : `/${path}`}`;
        const headers = new Headers(init.headers);
        headers.set('Accept', 'application/json');
        if (init.body && !headers.has('Content-Type')) {
            headers.set('Content-Type', 'application/json');
        }
        if (this.config.apiKey) {
            headers.set('Authorization', `Bearer ${this.config.apiKey}`);
        }
        const res = await fetch(url, { ...init, headers, cache: 'no-store' });
        const text = await res.text();
        if (!res.ok) throw new PmxtApiError(res.status, text);
        if (!text) return undefined as T;
        try {
            return JSON.parse(text) as T;
        } catch {
            // A 200 with an HTML error page (gateway, captive portal, broken
            // proxy) must surface as an actionable API error, not a raw
            // SyntaxError bubbling into widget error states.
            throw new PmxtApiError(
                res.status,
                JSON.stringify({
                    error: `Server returned non-JSON response from ${url}`,
                }),
            );
        }
    }

    private api<T>(path: string, init?: RequestInit): Promise<T> {
        return this.request<T>(this.config.apiUrl, path, init);
    }

    private trade<T>(path: string, init?: RequestInit): Promise<T> {
        const base = this.config.tradeUrl;
        if (!base) {
            throw new Error(
                'PmxtClient: `tradeUrl` is not configured — trading widgets need it.',
            );
        }
        return this.request<T>(base, path, init);
    }

    // ---- Catalog (market data, all venues) -----------------------------

    async fetchEvents(
        venue: CatalogVenue,
        opts: { limit?: number; query?: string } = {},
    ): Promise<PmxtEvent[]> {
        const params = new URLSearchParams();
        if (opts.limit) params.set('limit', String(opts.limit));
        if (opts.query) params.set('query', opts.query);
        const raw = await this.api<unknown>(`/api/${venue}/fetchEvents?${params}`);
        return unwrapEnvelope<PmxtEvent[]>(raw) ?? [];
    }

    async fetchMarkets(
        venue: CatalogVenue,
        opts: { query?: string; limit?: number } = {},
    ): Promise<PmxtMarket[]> {
        const params = new URLSearchParams();
        if (opts.query) params.set('query', opts.query);
        if (opts.limit) params.set('limit', String(opts.limit));
        const raw = await this.api<unknown>(`/api/${venue}/fetchMarkets?${params}`);
        return unwrapEnvelope<PmxtMarket[]>(raw) ?? [];
    }

    async fetchOrderBook(
        venue: CatalogVenue,
        outcomeId: string,
        depth = 10,
    ): Promise<OrderBook> {
        const params = new URLSearchParams({
            outcomeId,
            limit: String(depth),
        });
        let raw: unknown;
        try {
            raw = await this.api<unknown>(`/api/${venue}/fetchOrderBook?${params}`);
        } catch (err: unknown) {
            // A missing book is a normal market state (resolved/illiquid),
            // not an exceptional failure — surface it as an empty book.
            if (err instanceof PmxtApiError && err.status === 404) {
                return { bids: [], asks: [] };
            }
            throw err;
        }
        const book = unwrapEnvelope<OrderBook>(raw);
        // The catalog can return more levels than asked — trim client-side.
        return {
            bids: (book?.bids ?? []).slice(0, depth),
            asks: (book?.asks ?? []).slice(0, depth),
        };
    }

    async fetchOHLCV(
        venue: CatalogVenue,
        outcomeId: string,
        opts: { resolution?: string; limit?: number } = {},
    ): Promise<PriceCandle[]> {
        const params = new URLSearchParams({
            outcomeId,
            resolution: opts.resolution ?? '1h',
            limit: String(opts.limit ?? 100),
        });
        const raw = await this.api<unknown>(`/api/${venue}/fetchOHLCV?${params}`);
        return unwrapEnvelope<PriceCandle[]>(raw) ?? [];
    }

    async fetchTrades(
        venue: CatalogVenue,
        outcomeId: string,
        limit = 25,
    ): Promise<PublicTrade[]> {
        const params = new URLSearchParams({ outcomeId, limit: String(limit) });
        const raw = await this.api<unknown>(`/api/${venue}/fetchTrades?${params}`);
        const trades = unwrapEnvelope<unknown[]>(raw) ?? [];
        return trades.map(normalizeTrade).filter((t): t is PublicTrade => t !== null);
    }

    async fetchClusters(
        opts: { query?: string; limit?: number } = {},
    ): Promise<MarketCluster[]> {
        const params = new URLSearchParams({ limit: String(opts.limit ?? 50) });
        if (opts.query) params.set('q', opts.query);
        const raw = await this.api<unknown>(`/v0/matched-market-clusters?${params}`);
        return unwrapEnvelope<MarketCluster[]>(raw) ?? [];
    }

    /**
     * Query-filtered cross-venue market matches from the PMXT router
     * (`/api/router/fetchMarketMatches`). Unlike the clusters endpoint,
     * this one actually honors `query`.
     */
    async fetchMarketMatches(
        opts: { query?: string; limit?: number } = {},
    ): Promise<MarketMatch[]> {
        const params = new URLSearchParams({ limit: String(opts.limit ?? 20) });
        if (opts.query) params.set('query', opts.query);
        const raw = await this.api<unknown>(
            `/api/router/fetchMarketMatches?${params}`,
        );
        return unwrapEnvelope<MarketMatch[]>(raw) ?? [];
    }

    /** Cross-venue matched EVENTS from `/v0/matched-event-clusters`. */
    async fetchEventClusters(
        opts: { query?: string; limit?: number } = {},
    ): Promise<EventCluster[]> {
        const params = new URLSearchParams({ limit: String(opts.limit ?? 50) });
        if (opts.query) params.set('q', opts.query);
        const raw = await this.api<unknown>(`/v0/matched-event-clusters?${params}`);
        return unwrapEnvelope<EventCluster[]>(raw) ?? [];
    }

    // ---- Hosted trading (documented /v0 surface) ------------------------

    /** `POST /v0/trade/build-order` — returns EIP-712 typed data + a quote. */
    buildOrder(body: BuildOrderRequest): Promise<BuiltOrder> {
        return this.trade<BuiltOrder>('/v0/trade/build-order', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /** `POST /v0/trade/submit-order` — submit the signed build by id. */
    submitOrder(args: SubmitOrderRequest): Promise<PmxtOrder> {
        const body: SubmitOrderRequest = { wait: true, ...args };
        return this.trade<PmxtOrder>('/v0/trade/submit-order', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /**
     * `GET /v0/orders/{order_id}` — current lifecycle status of a submitted
     * order, projected from the operator's task_state_log. Used to drive
     * real-time progress while a submission settles on-chain.
     */
    fetchOrder(orderId: string): Promise<PmxtOrder> {
        return this.trade<PmxtOrder>(
            `/v0/orders/${encodeURIComponent(orderId)}`,
        );
    }

    async fetchBalances(address: string): Promise<PmxtBalance[]> {
        const res = await this.trade<unknown>(
            `/v0/user/${encodeURIComponent(address)}/balances`,
        );
        return toArray<PmxtBalance>(res, 'balances');
    }

    async fetchPositions(address: string): Promise<PmxtPosition[]> {
        const res = await this.trade<unknown>(
            `/v0/user/${encodeURIComponent(address)}/positions`,
        );
        return toArray<PmxtPosition>(res, 'positions');
    }

    async fetchOpenOrders(address: string): Promise<PmxtOrder[]> {
        const res = await this.trade<unknown>(
            `/v0/orders/open?address=${encodeURIComponent(address)}`,
        );
        return toArray<PmxtOrder>(res, 'orders');
    }

    async fetchUserTrades(address: string, limit?: number): Promise<PmxtUserTrade[]> {
        const params = new URLSearchParams();
        if (limit) params.set('limit', String(limit));
        const qs = params.toString();
        const res = await this.trade<unknown>(
            `/v0/user/${encodeURIComponent(address)}/trades${qs ? `?${qs}` : ''}`,
        );
        return toArray<PmxtUserTrade>(res, 'trades');
    }

    /** `POST /v0/orders/cancel/build` — returns cancel typed data + cancel_id. */
    buildCancel(body: CancelBuildRequest): Promise<CancelBuildResponse> {
        return this.trade<CancelBuildResponse>('/v0/orders/cancel/build', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /** `POST /v0/orders/cancel` — submit the signed cancel by id. */
    cancelOrder(body: CancelRequest): Promise<PmxtOrder> {
        return this.trade<PmxtOrder>('/v0/orders/cancel', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    // ---- Escrow funding (deposit / withdraw) ----------------------------

    /** `POST /escrow/build-approve` — unsigned ERC-20 approve tx for the escrow. */
    buildApprove(body: {
        token: 'usdc' | 'ctf';
        user_address: string;
        amount_wei?: number;
    }): Promise<BuildTxResponse> {
        return this.trade<BuildTxResponse>('/escrow/build-approve', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /** `POST /escrow/build-deposit` — unsigned deposit tx into PreFundedEscrow. */
    buildDeposit(body: {
        token: string;
        amount: number;
        user_address?: string;
    }): Promise<BuildTxResponse> {
        return this.trade<BuildTxResponse>('/escrow/build-deposit', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /**
     * `POST /escrow/build-withdrawal` — unsigned tx for the timelocked
     * withdrawal lifecycle: `request` starts it, `claim` completes it once
     * the timelock elapses, `cancel` aborts it.
     */
    buildWithdrawal(body: {
        action: 'request' | 'claim' | 'cancel';
        amount?: number;
        user_address?: string;
    }): Promise<BuildTxResponse> {
        return this.trade<BuildTxResponse>('/escrow/build-withdrawal', {
            method: 'POST',
            body: JSON.stringify(body),
        });
    }

    /** `GET /escrow/withdrawals/{address}` — pending withdrawal and/or events. */
    fetchWithdrawals(
        address: string,
        include: 'pending' | 'events' | 'pending,events' = 'pending,events',
    ): Promise<WithdrawalsResponse> {
        return this.trade<WithdrawalsResponse>(
            `/escrow/withdrawals/${encodeURIComponent(address)}?include=${include}`,
        );
    }

    /** `GET /user/escrow-balances` — USDC + wrapped-token escrow balances. */
    fetchEscrowBalances(
        address: string,
        tokenAddress = 'all',
    ): Promise<EscrowBalancesResponse> {
        const params = new URLSearchParams({
            address,
            token_address: tokenAddress,
        });
        return this.trade<EscrowBalancesResponse>(
            `/user/escrow-balances?${params}`,
        );
    }
}

/**
 * v0 reads return bare arrays today; tolerate `{key: [...]}` envelopes too.
 * Anything else throws — silently returning [] would make a failed fetch
 * indistinguishable from a genuinely empty account ("No positions yet").
 */
function toArray<T>(raw: unknown, key: string): T[] {
    if (raw == null) return [];
    if (Array.isArray(raw)) return raw as T[];
    if (typeof raw === 'object') {
        const obj = raw as Record<string, unknown>;
        const wrapped = obj[key];
        if (Array.isArray(wrapped)) return wrapped as T[];
        if (Object.keys(obj).length === 0) return [];
    }
    throw new PmxtApiError(
        502,
        JSON.stringify({ error: `Unexpected ${key} response shape` }),
    );
}

function normalizeTrade(raw: unknown): PublicTrade | null {
    if (raw == null || typeof raw !== 'object') return null;
    const t = raw as Record<string, unknown>;
    const price = toNumber(t.price);
    const amount = toNumber(t.amount ?? t.size ?? t.shares);
    if (price == null || amount == null) return null;
    const side = t.side === 'buy' || t.side === 'sell' ? t.side : null;
    const timestamp = toNumber(t.timestamp ?? t.ts ?? t.time);
    return { price, amount, side, timestamp };
}

function toNumber(value: unknown): number | null {
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    if (typeof value === 'string') {
        const n = Number.parseFloat(value);
        return Number.isFinite(n) ? n : null;
    }
    return null;
}

/**
 * Walk an orderbook to compute the volume-weighted average execution price
 * for a given share amount. Buys walk the asks, sells walk the bids.
 */
export function getExecutionPrice(
    book: OrderBook,
    side: 'buy' | 'sell',
    amount: number,
): ExecutionPrice {
    const levels = side === 'buy' ? book.asks : book.bids;
    let remaining = amount;
    let totalCost = 0;
    let filled = 0;
    for (const level of levels) {
        if (remaining <= 0) break;
        const take = Math.min(remaining, level.size);
        totalCost += take * level.price;
        filled += take;
        remaining -= take;
    }
    return {
        averagePrice: filled > 0 ? totalCost / filled : 0,
        filledAmount: filled,
        totalCost,
        partialFill: filled < amount,
    };
}

import type { TypedData, UnsignedTx } from './types';

/** Minimal EIP-1193 provider surface the trading widgets need. */
export interface Eip1193Provider {
    request: (args: { method: string; params?: unknown[] }) => Promise<unknown>;
    on?: (event: string, handler: (...args: unknown[]) => void) => void;
    removeListener?: (
        event: string,
        handler: (...args: unknown[]) => void,
    ) => void;
}

/** Polygon mainnet chain id. */
export const POLYGON_CHAIN_ID = 137;

interface InjectedProvider extends Eip1193Provider {
    isMetaMask?: boolean;
    isPhantom?: boolean;
    /** Multi-wallet pages expose every injected provider here. */
    providers?: InjectedProvider[];
}

/** Injected wallets the widgets can connect to, in priority order. */
export type WalletId = 'metamask' | 'phantom';

export const SUPPORTED_WALLETS: readonly WalletId[] = ['metamask', 'phantom'];

export const WALLET_LABELS: Record<WalletId, string> = {
    metamask: 'MetaMask',
    phantom: 'Phantom',
};

function injectedCandidates(): InjectedProvider[] {
    const g = globalThis as {
        ethereum?: InjectedProvider;
        phantom?: { ethereum?: InjectedProvider };
    };
    const eth = g.ethereum;
    const candidates = eth?.providers?.length
        ? [...eth.providers]
        : eth
          ? [eth]
          : [];
    // Phantom always exposes its EVM provider here, even when another wallet
    // occupies window.ethereum.
    const phantom = g.phantom?.ethereum;
    if (phantom && !candidates.includes(phantom)) {
        candidates.push(phantom);
    }
    return candidates;
}

function findWalletProvider(id: WalletId): InjectedProvider | undefined {
    const candidates = injectedCandidates();
    if (id === 'metamask') {
        // Phantom spoofs `isMetaMask` for dapp compatibility — exclude it.
        return candidates.find((p) => p.isMetaMask && !p.isPhantom);
    }
    return candidates.find((p) => p.isPhantom);
}

/** Wallets currently installed on the page, in connect-priority order. */
export function detectWallets(): WalletId[] {
    return SUPPORTED_WALLETS.filter((id) => findWalletProvider(id));
}

/**
 * The injected provider for `walletId`; throws when that wallet is not
 * installed. Without an argument, returns the first installed supported
 * wallet (MetaMask, then Phantom). Other injected wallets (Coinbase, Rabby,
 * Brave, …) are rejected even when they occupy `window.ethereum`.
 */
export function getInjectedProvider(walletId?: WalletId): Eip1193Provider {
    if (walletId) {
        const provider = findWalletProvider(walletId);
        if (!provider) {
            throw new Error(
                `${WALLET_LABELS[walletId]} not found. Install ${WALLET_LABELS[walletId]} to connect.`,
            );
        }
        return provider;
    }
    const provider = SUPPORTED_WALLETS.map(findWalletProvider).find(Boolean);
    if (!provider) {
        throw new Error(
            'No supported wallet found. Install MetaMask or Phantom to connect — other wallets are not supported.',
        );
    }
    return provider;
}

/** Prompts the wallet to connect and returns the authorized accounts. */
export async function requestAccounts(
    provider: Eip1193Provider,
): Promise<`0x${string}`[]> {
    const accounts = (await provider.request({
        method: 'eth_requestAccounts',
    })) as string[];
    return accounts as `0x${string}`[];
}

/**
 * Returns already-authorized accounts without prompting (`eth_accounts`).
 * Empty when the site has no active wallet authorization.
 */
export async function getAuthorizedAccounts(
    provider: Eip1193Provider,
): Promise<`0x${string}`[]> {
    const accounts = (await provider.request({
        method: 'eth_accounts',
    })) as string[];
    return accounts as `0x${string}`[];
}

/** Asks the wallet to switch to `chainId` (`wallet_switchEthereumChain`). */
export async function switchChain(
    provider: Eip1193Provider,
    chainId: number,
): Promise<void> {
    await provider.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: `0x${chainId.toString(16)}` }],
    });
}

/** Signs EIP-712 typed data via `eth_signTypedData_v4`. */
export async function signTypedData(
    provider: Eip1193Provider,
    address: string,
    typed: TypedData,
): Promise<`0x${string}`> {
    const sig = await provider.request({
        method: 'eth_signTypedData_v4',
        params: [
            address.toLowerCase(),
            JSON.stringify({
                types: typed.types,
                primaryType: typed.primaryType,
                domain: typed.domain,
                message: typed.message,
            }),
        ],
    });
    return sig as `0x${string}`;
}

/** Polygon USDC.e (bridged USDC) — the token PreFundedEscrow accepts. */
export const USDC_E_ADDRESS: `0x${string}` =
    '0x2791Bca1f2de4661ED88A30C99A7a9449Aa84174';

/** Wei units per whole USDC (6 decimals). */
export const MICRO_USDC = BigInt(1_000_000);

/** Sends an unsigned tx via `eth_sendTransaction`; returns the tx hash. */
export async function sendTransaction(
    provider: Eip1193Provider,
    from: `0x${string}`,
    tx: UnsignedTx,
): Promise<`0x${string}`> {
    const hash = await provider.request({
        method: 'eth_sendTransaction',
        params: [
            {
                from,
                to: tx.to,
                data: tx.data,
                value: `0x${BigInt(tx.value || '0').toString(16)}`,
            },
        ],
    });
    return hash as `0x${string}`;
}

/**
 * Polls `eth_getTransactionReceipt` until the tx is mined. Throws when the
 * receipt reports a revert or the timeout elapses.
 */
export async function waitForTransactionReceipt(
    provider: Eip1193Provider,
    hash: `0x${string}`,
    opts: { pollMs?: number; timeoutMs?: number } = {},
): Promise<void> {
    const { pollMs = 2_000, timeoutMs = 120_000 } = opts;
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
        let receipt: { status?: string } | null = null;
        try {
            receipt = (await provider.request({
                method: 'eth_getTransactionReceipt',
                params: [hash],
            })) as { status?: string } | null;
        } catch {
            // Transient RPC errors ("Unknown block") are normal while the
            // node catches up — keep polling until the deadline.
        }
        if (receipt) {
            if (receipt.status === '0x0') {
                throw new Error(`Transaction ${hash} reverted on-chain.`);
            }
            return;
        }
        await new Promise((resolve) => setTimeout(resolve, pollMs));
    }
    throw new Error(
        `Timed out waiting for transaction ${hash} to be mined (${timeoutMs / 1000}s).`,
    );
}

/** Reads `allowance(owner, spender)` on an ERC-20 via `eth_call`. */
export async function readErc20Allowance(
    provider: Eip1193Provider,
    token: `0x${string}`,
    owner: `0x${string}`,
    spender: `0x${string}`,
): Promise<bigint> {
    // allowance(address,address) selector + two left-padded address args.
    const data = `0xdd62ed3e${pad32(owner)}${pad32(spender)}`;
    const result = (await provider.request({
        method: 'eth_call',
        params: [{ to: token, data }, 'latest'],
    })) as string;
    return result && result !== '0x' ? BigInt(result) : BigInt(0);
}

/** Reads `balanceOf(account)` on an ERC-20 via `eth_call`. */
export async function readErc20Balance(
    provider: Eip1193Provider,
    token: `0x${string}`,
    account: `0x${string}`,
): Promise<bigint> {
    // balanceOf(address) selector + left-padded address arg.
    const data = `0x70a08231${pad32(account)}`;
    const result = (await provider.request({
        method: 'eth_call',
        params: [{ to: token, data }, 'latest'],
    })) as string;
    return result && result !== '0x' ? BigInt(result) : BigInt(0);
}

/** Reads the native (POL) balance of an account. */
export async function readNativeBalance(
    provider: Eip1193Provider,
    account: `0x${string}`,
): Promise<bigint> {
    const result = (await provider.request({
        method: 'eth_getBalance',
        params: [account, 'latest'],
    })) as string;
    return result && result !== '0x' ? BigInt(result) : BigInt(0);
}

/** Calldata for `approve(spender, amount)` on an ERC-20. */
export function encodeErc20Approve(
    spender: `0x${string}`,
    amount: bigint,
): `0x${string}` {
    return `0x095ea7b3${pad32(spender)}${amount
        .toString(16)
        .padStart(64, '0')}` as `0x${string}`;
}

function pad32(address: string): string {
    return address.toLowerCase().replace(/^0x/, '').padStart(64, '0');
}

/**
 * Pluggable signer used by OrderTicket / OpenOrdersTable. The default
 * implementation talks to the injected wallet; pass your own (wagmi, privy,
 * embedded wallets, …) through PmxtProvider to override it.
 */
export interface PmxtSigner {
    /** Sign EIP-712 typed data on the chain declared in `typed.domain.chainId`. */
    signTypedData: (typed: TypedData) => Promise<`0x${string}`>;
}

/** PmxtSigner backed by the injected wallet; switches chain before each signature. */
export function createInjectedSigner(
    address: string,
    walletId?: WalletId,
): PmxtSigner {
    return {
        async signTypedData(typed: TypedData) {
            const provider = getInjectedProvider(walletId);
            await switchChain(provider, Number(typed.domain.chainId));
            return signTypedData(provider, address, typed);
        },
    };
}

import type { CatalogVenue, TradingVenue } from './types';

/**
 * Accent colors are overridable via CSS custom properties (set them on any
 * ancestor of the widgets):
 *
 * - `--pmxt-accent` / `--pmxt-accent-hover` / `--pmxt-accent-tint` —
 *   Polymarket accent (button bg, hover bg, text, light tint, dot).
 * - `--pmxt-accent-opinion` / `--pmxt-accent-opinion-hover` /
 *   `--pmxt-accent-opinion-tint` — same set for Opinion.
 * - `--pmxt-positive` / `--pmxt-negative` — buy/Yes and sell/No accents
 *   used by the trade panels (InlineTradePanel, OrderTicket).
 * - `--pmxt-surface` / `--pmxt-surface-dark` — background of every widget's
 *   root card surface in light / dark mode (defaults `#ffffff` / `#18181b`).
