'use client';

import {
    createContext,
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState,
    type ReactNode,
} from 'react';
import { PmxtClient, type PmxtClientConfig } from './client';
import {
    SANDBOX_ADDRESS,
    SandboxPmxtClient,
    SandboxSession,
} from './sandbox';
import {
    createInjectedSigner,
    detectWallets,
    getAuthorizedAccounts,
    getInjectedProvider,
    requestAccounts,
    type PmxtSigner,
    type WalletId,
} from './wallet';

/**
 * Set after an explicit disconnect so the silent `eth_accounts` restore on
 * mount doesn't immediately re-connect — the wallet itself stays authorized
 * until the user revokes the site in the extension.
 */
const DISCONNECTED_KEY = 'pmxt-widgets:disconnected';
const LAST_WALLET_KEY = 'pmxt-widgets:last-wallet';

function rememberDisconnected(disconnected: boolean): void {
    try {
        if (disconnected) {
            window.localStorage.setItem(DISCONNECTED_KEY, '1');
        } else {
            window.localStorage.removeItem(DISCONNECTED_KEY);
        }
    } catch {
        // Storage unavailable (SSR, privacy mode) — restore just won't persist.
    }
}

function wasDisconnected(): boolean {
    try {
        return window.localStorage.getItem(DISCONNECTED_KEY) === '1';
    } catch {
        return false;
    }
}

function rememberLastWallet(id: WalletId | null): void {
    try {
        if (id) {
            window.localStorage.setItem(LAST_WALLET_KEY, id);
        } else {
            window.localStorage.removeItem(LAST_WALLET_KEY);
        }
    } catch {
        // Storage unavailable — restore falls back to detection order.
    }
}

function readLastWallet(): WalletId | null {
    try {
        const v = window.localStorage.getItem(LAST_WALLET_KEY);
        return v === 'metamask' || v === 'phantom' ? v : null;
    } catch {
        return null;
    }
}

export interface PmxtWalletState {
    /** Connected account, or null when no wallet is connected. */
    address: `0x${string}` | null;
    /** Which injected wallet is connected, or null. */
    walletId: WalletId | null;
    /** Installed supported wallets, in connect-priority order. */
    availableWallets: WalletId[];
    /** True while a connect request is pending in the wallet. */
    connecting: boolean;
    /** Why the last connect attempt failed (e.g. user rejected), or null. */
    connectError: string | null;
    /** Connects `walletId`, or the first installed wallet when omitted. */
    connect: (walletId?: WalletId) => Promise<void>;
    disconnect: () => void;
    /**
     * True when the provider manages the connection itself (injected wallet)
     * and `disconnect` actually does something. False in sandbox and
     * bring-your-own-wallet modes, where the host owns the connection.
     */
    canDisconnect: boolean;
    /** EIP-712 signer for the connected account, or null. */
    signer: PmxtSigner | null;
}

interface PmxtContextValue {
    client: PmxtClient;
    wallet: PmxtWalletState;
    /** Present when the provider runs in sandbox mode; null for live trading. */
    sandbox: SandboxSession | null;
}

const PmxtContext = createContext<PmxtContextValue | null>(null);

export interface PmxtProviderProps {
    config: PmxtClientConfig;
    /**
     * Bring-your-own wallet: pass a connected address + signer (e.g. from
     * wagmi) and the built-in injected-wallet connect flow is bypassed.
     */
    wallet?: { address: `0x${string}`; signer: PmxtSigner };
    /**
     * Sandbox mode: market data stays live, but trading is fully simulated —
     * a built-in demo wallet, $1,000 of play money, and in-memory fills.
     * No order ever reaches the trading API. Great for demos and try-outs.
     */
    sandbox?: boolean;
    children: ReactNode;
}

/** A signer that "signs" after a short delay — sandbox UX stand-in. */
const sandboxSigner: PmxtSigner = {
    async signTypedData() {
        await new Promise((resolve) => setTimeout(resolve, 600));
        return `0x${'ab'.repeat(65)}` as `0x${string}`;
    },
};

/**
 * Context root for every PMXT widget: builds the API client, manages the
 * wallet connection (injected by default, bring-your-own via `wallet`,
 * or simulated via `sandbox`), and hands both down through `usePmxt`.
 */
export function PmxtProvider({
    config,
    wallet,
    sandbox = false,
    children,
}: PmxtProviderProps) {
    const session = useMemo(
        () => (sandbox ? new SandboxSession() : null),
        [sandbox],
    );
    const client = useMemo(
        () =>
            session
                ? new SandboxPmxtClient(config, session)
                : new PmxtClient(config),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [config.apiUrl, config.tradeUrl, config.apiKey, session],
    );

    const [injectedAddress, setInjectedAddress] = useState<`0x${string}` | null>(
        null,
    );
    const [connectedWallet, setConnectedWallet] = useState<WalletId | null>(
        null,
    );
    const [availableWallets, setAvailableWallets] = useState<WalletId[]>([]);
    const [connecting, setConnecting] = useState(false);
    const [connectError, setConnectError] = useState<string | null>(null);

    // Detection must run client-side (no window during SSR).
    useEffect(() => {
        if (wallet || sandbox) return;
        setAvailableWallets(detectWallets());
    }, [wallet, sandbox]);

    // Silently restore an existing authorization (no wallet popup) so the
    // connection survives navigation and reloads — unless the user
    // explicitly disconnected. Prefer the wallet the user most recently
    // connected; only fall back to detection order when no preference is
    // remembered (e.g. first visit, or storage cleared).
    useEffect(() => {
        if (wallet || sandbox || wasDisconnected()) return;
        let cancelled = false;
        (async () => {
            const detected = detectWallets();
            const last = readLastWallet();
            const order: WalletId[] =
                last && detected.includes(last)
                    ? [last, ...detected.filter((id) => id !== last)]
                    : detected;
            for (const id of order) {
                try {
                    const accounts = await getAuthorizedAccounts(
                        getInjectedProvider(id),
                    );
                    if (cancelled) return;
                    if (accounts[0]) {
                        setInjectedAddress(accounts[0]);
                        setConnectedWallet(id);
                        return;
                    }
                } catch {
                    // Provider unavailable or rejected the call — try the next.
                }
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [wallet, sandbox]);

    // Follow account switches in the connected wallet's extension.
    useEffect(() => {
        if (wallet || sandbox || !connectedWallet) return;
        let eth;
        try {
            eth = getInjectedProvider(connectedWallet);
        } catch {
            return;
        }
        const onAccounts = (...args: unknown[]) => {
            const accounts = args[0] as string[];
            setInjectedAddress((accounts[0] as `0x${string}`) ?? null);
        };
        eth.on?.('accountsChanged', onAccounts);
        return () => {
            eth?.removeListener?.('accountsChanged', onAccounts);
        };
    }, [wallet, sandbox, connectedWallet]);

    const connect = useCallback(async (walletId?: WalletId) => {
        setConnecting(true);
        setConnectError(null);
        try {
            const id = walletId ?? detectWallets()[0];
            const accounts = await requestAccounts(getInjectedProvider(id));
            setInjectedAddress(accounts[0] ?? null);
            if (accounts[0]) {
                setConnectedWallet(id ?? null);
                rememberDisconnected(false);
                rememberLastWallet(id ?? null);
            }
        } catch (err: unknown) {
            // A rejected prompt must not vanish silently — surface it so
            // connect buttons can tell the user what happened.
            setConnectError(
                err instanceof Error ? err.message : 'Wallet connection failed',
            );
        } finally {
            setConnecting(false);
        }
    }, []);

    const disconnect = useCallback(() => {
        rememberDisconnected(true);
        rememberLastWallet(null);
        setInjectedAddress(null);
        setConnectedWallet(null);
    }, []);

    const walletState = useMemo<PmxtWalletState>(() => {
        if (sandbox) {
            return {
                address: SANDBOX_ADDRESS,
                walletId: null,
                availableWallets: [],
                connecting: false,
                connectError: null,
                connect: async () => {},
                disconnect: () => {},
                canDisconnect: false,
                signer: sandboxSigner,
            };
        }
        if (wallet) {
            return {
                address: wallet.address,
                walletId: null,
                availableWallets: [],
                connecting: false,
                connectError: null,
                connect: async () => {},
                disconnect: () => {},
                canDisconnect: false,
                signer: wallet.signer,
            };
        }
        return {
            address: injectedAddress,
            walletId: connectedWallet,
            availableWallets,
            connecting,
            connectError,
            connect,
            disconnect,
            canDisconnect: true,
            signer: injectedAddress
                ? createInjectedSigner(injectedAddress, connectedWallet ?? undefined)
                : null,
        };
    }, [
        sandbox,
        wallet,
        injectedAddress,
        connectedWallet,
        availableWallets,
        connecting,
        connectError,
        connect,
        disconnect,
    ]);

    const value = useMemo(
        () => ({ client, wallet: walletState, sandbox: session }),
        [client, walletState, session],
    );

    return <PmxtContext.Provider value={value}>{children}</PmxtContext.Provider>;
}

/**
 * The client, wallet state, and sandbox session every widget runs on.
 * Throws when called outside a <PmxtProvider>.
 */
export function usePmxt(): PmxtContextValue {
    const ctx = useContext(PmxtContext);
    if (!ctx) {
        throw new Error('PMXT widgets must be rendered inside <PmxtProvider>.');
    }
    return ctx;
}

/**
 * Non-throwing variant for display widgets that upgrade to trading UI only
 * when a provider is present (e.g. MarketCard's built-in expand-to-trade).
 */
export function usePmxtOptional(): PmxtContextValue | null {
    return useContext(PmxtContext);
}

/** Wallet slice of the PMXT context: address, connect/disconnect, signer. */
export function usePmxtWallet(): PmxtWalletState {
    return usePmxt().wallet;
}

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { usePmxt } from './provider';
import type {
    CatalogVenue,
    EscrowBalancesResponse,
    EventCluster,
    MarketCluster,
    OrderBook,
    PmxtBalance,
    PmxtEvent,
    PmxtMarket,
    PmxtOrder,
    PmxtPosition,
    PmxtUserTrade,
    PriceCandle,
    PublicTrade,
    WithdrawalsResponse,
} from './types';

/** Return shape of every data hook. */
export interface QueryState<T> {
    /** Last successful result; null until the first fetch resolves. */
    data: T | null;
    /** Message from the most recent failed fetch; cleared on success. */
    error: string | null;
    /** True while the initial fetch is in flight. */
    loading: boolean;
    /** Re-run the fetch immediately. */
    refetch: () => void;
}

/** Options accepted by `usePmxtQuery`. */
export interface QueryOptions {
    /** Re-fetch on an interval (ms). Omit for fetch-once. */
    refetchInterval?: number;
    /** Skip fetching while false. */
    enabled?: boolean;
}

/**
 * Dependency-free data hook: fetch on mount, optional polling, stale-response
 * protection. Deliberately tiny so copy-pasted widgets carry no react-query
 * peer dependency — swap in your own data layer if you have one.
 */
export function usePmxtQuery<T>(
    key: ReadonlyArray<string | number | boolean | null | undefined>,
    fetcher: () => Promise<T>,
    options: QueryOptions = {},
): QueryState<T> {
    const { refetchInterval, enabled = true } = options;
    const [data, setData] = useState<T | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(enabled);
    const generation = useRef(0);
    const fetcherRef = useRef(fetcher);
    fetcherRef.current = fetcher;

    const serializedKey = JSON.stringify(key);

    const run = useCallback(async () => {
        const gen = ++generation.current;
        try {
            const result = await fetcherRef.current();
            if (gen !== generation.current) return;
            setData(result);
            setError(null);
        } catch (err: unknown) {
            if (gen !== generation.current) return;
            setError(err instanceof Error ? err.message : 'Request failed');
        } finally {
            if (gen === generation.current) setLoading(false);
        }
    }, [serializedKey]);

    useEffect(() => {
        if (!enabled) return;
        setLoading(true);
        void run();
        if (!refetchInterval) return;
        const id = setInterval(() => void run(), refetchInterval);
        return () => clearInterval(id);
    }, [run, enabled, refetchInterval]);

    return { data, error, loading, refetch: run };
}

/** Returns `value` once it has been stable for `delayMs` (default 300ms). */
export function useDebounced<T>(value: T, delayMs = 300): T {
    const [debounced, setDebounced] = useState(value);
    useEffect(() => {
        const id = setTimeout(() => setDebounced(value), delayMs);
        return () => clearTimeout(id);
    }, [value, delayMs]);
    return debounced;
}

// ---- Data hooks ---------------------------------------------------------

/**
 * Catalog events (with nested markets) for a venue, optionally filtered by
 * `query`. Polls every 60s by default.
 */
export function useEvents(
    venue: CatalogVenue,
    opts: {
        limit?: number;
        query?: string;
        refetchInterval?: number;
        enabled?: boolean;
    } = {},
): QueryState<PmxtEvent[]> {
    const { client } = usePmxt();
    return usePmxtQuery(
        ['events', venue, opts.limit, opts.query],
        () => client.fetchEvents(venue, opts),
        {
            refetchInterval: opts.refetchInterval ?? 60_000,
            enabled: opts.enabled ?? true,
        },
    );
}

/**
 * Events from every venue in parallel, merged into one list. A venue that
 * errors is skipped (partial results beat none); errors only when every
 * venue fails. Polls every 60s.
 */
export function useUnifiedEvents(
    venues: CatalogVenue[],
    opts: { limit?: number; query?: string; enabled?: boolean } = {},
): QueryState<VenueEvent[]> {
    const { client } = usePmxt();
    return usePmxtQuery(
        ['unified-events', venues.join(','), opts.limit, opts.query],
        async () => {
            const settled = await Promise.allSettled(
                venues.map(async (venue) => {
                    const events = await client.fetchEvents(venue, {
                        limit: opts.limit ?? 10,
                        query: opts.query,
                    });
                    return events.map((event) => ({ venue, event }));
                }),
            );
            const hits = settled
                .filter(
                    (r): r is PromiseFulfilledResult<VenueEvent[]> =>
                        r.status === 'fulfilled',
                )
                .flatMap((r) => r.value);
            if (
                hits.length === 0 &&
                settled.every((r) => r.status === 'rejected')
            ) {
                throw new Error('Every venue failed to load');
            }
            return hits;
        },
        { refetchInterval: 60_000, enabled: opts.enabled ?? true },
    );
}

/**
 * Catalog market search on one venue. Skips fetching while `query` is
 * empty/whitespace; fetch-once (no polling). Default limit 20.
 */
export function useMarketSearch(
    venue: CatalogVenue,
    query: string,
    opts: { limit?: number; enabled?: boolean } = {},
): QueryState<PmxtMarket[]> {
    const { client } = usePmxt();
    return usePmxtQuery(
        ['market-search', venue, query, opts.limit],
        () => client.fetchMarkets(venue, { query, limit: opts.limit ?? 20 }),
        { enabled: (opts.enabled ?? true) && query.trim().length > 0 },
    );
}

/** One unified-search hit: the market plus the venue it was found on. */
export interface VenueMarket {
    venue: CatalogVenue;
    market: PmxtMarket;
}

/** One unified-search hit: the event plus the venue it was found on. */
export interface VenueEvent {
    venue: CatalogVenue;
    event: PmxtEvent;
}

/**
 * Unified market search: queries every venue in parallel and merges the
 * results by 24h volume. A venue that errors is skipped (partial results
 * beat none); the hook only errors when every venue fails. Skips fetching
 * while `query` is empty.
 */
export function useUnifiedMarketSearch(
    venues: CatalogVenue[],
    query: string,
    opts: { limit?: number; enabled?: boolean } = {},
): QueryState<VenueMarket[]> {
    const { client } = usePmxt();
    return usePmxtQuery(
        ['unified-market-search', venues.join(','), query, opts.limit],
        async () => {
            const settled = await Promise.allSettled(
                venues.map(async (venue) => {
                    const markets = await client.fetchMarkets(venue, {
                        query,
                        limit: opts.limit ?? 10,
                    });
                    return markets.map((market) => ({ venue, market }));
                }),
            );
            const hits = settled
                .filter(
                    (r): r is PromiseFulfilledResult<VenueMarket[]> =>
                        r.status === 'fulfilled',
                )
                .flatMap((r) => r.value);
            if (hits.length === 0 && settled.every((r) => r.status === 'rejected')) {
                throw new Error('Search failed on every venue');
            }
            return hits.sort(
                (a, b) =>
                    (b.market.volume24h ?? 0) - (a.market.volume24h ?? 0),
            );
        },
        { enabled: (opts.enabled ?? true) && query.trim().length > 0 },
    );
}

